func testProductEditingRequiredErrorKeepsInputAndAllowsCorrection() throws {
    let app = makeApplication()
    app.launch()
    try registerAndOpenDetail(name: "Before", type: "Type", in: app)
    openEditing(in: app)
    try replaceFormValue("   ", field: "product-form-name", in: app)
    try replaceFormValue("Edited", field: "product-form-type", in: app)

    app.buttons["product-form-save"].tap()

    XCTAssertTrue(app.staticTexts["product-form-name-error"].waitForExistence(timeout: 5))
    XCTAssertTrue(app.navigationBars["商品編集"].exists)
    assertForm(name: "   ", type: "Edited", in: app)
    try replaceFormValue("Corrected", field: "product-form-name", in: app)
    app.buttons["product-form-save"].tap()

    assertDetail(name: "Corrected", type: "Edited", in: app)

@Test func deletionCountsIncludeEveryStateAndExcludeOtherProducts() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = try Product(name: "しょうゆ", type: "調味料")
    let other = try Product(name: "しょうゆ", type: "調味料")
    context.insert(product)
    context.insert(other)
    let states = ["unopened", "unopened", "inUse", "consumed", "consumed", "consumed", "future"]
    for state in states {
        let item = Item(product: product)
        item.setValue(forKey: \.statusRawValue, to: state)
        context.insert(item)
    }
    context.insert(Item(product: other))
    try context.save()

    let reader = ModelContext(container)
    let items = try reader.fetch(ProductDetailView.itemDescriptor(for: product.id))
    let counts = ProductDeletionCounts(items: items)

    #expect(items.count == states.count)
    #expect(items.allSatisfy { $0.product?.id == product.id })
    #expect(counts.unopened == 2)
    #expect(counts.inUse == 1)
    #expect(counts.history == 3)
    #expect(counts.unknown == 1)
    #expect(!counts.canDelete)
    #expect(!reader.hasChanges)

@Test func deletionRechecksItemsSavedByAnotherContext() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let actions = ProductActions(context: context)
    let product = try actions.create(from: populatedDraft(), image: originalImage, now: originalDate).get()
    #expect((product.items ?? []).isEmpty)

    let writer = ModelContext(container)
    let savedProduct = try #require(writer.fetch(FetchDescriptor<Product>()).first)
    let item = makeItem(product: savedProduct, status: .unopened)
    writer.insert(item)
    try writer.save()

    // 手元のリレーションが空だった商品も、削除時点のストアを再照会する。
    guard case .failure(.productHasItems(count: 1)) = actions.delete(product, confirmed: true) else {
        Issue.record("期待した失敗結果が返されなかった")
        return
    }

    expectOriginalValues(product)
    #expect(!context.hasChanges)
    let reader = ModelContext(container)
    let savedItem = try #require(reader.fetch(FetchDescriptor<Item>()).first)
    #expect(savedItem.id == item.id)
    #expect(savedItem.product?.id == product.id)
    #expect(try reader.fetchCount(FetchDescriptor<Product>()) == 1)
}

private struct ProductBasicFieldsView: View {
    @Binding var name: String
    @Binding var type: String
    let nameError: String?
    let typeError: String?

    var body: some View {
        Section {
            TextField("名前", text: $name)
                .accessibilityLabel("名前、必須")
                .accessibilityHint(nameError ?? "商品の名前を入力してください。")
                .accessibilityIdentifier("product-form-name")

            if let nameError {
                Text(nameError)
                    .foregroundStyle(.red)
                    .accessibilityLabel("名前のエラー、\(nameError)")

        ProductDeletionSection(
            counts: ProductDeletionCounts(items: items),
            fetchErrorMessage: _items.fetchError?.localizedDescription,
            deletionError: deletionError,
            onRequestDelete: { requestDeletion() }
        )
    }
}

private func requestDeletion() {
    deletionError = nil
    showsDeletionConfirmation = true
}

var body: some View {
    Form {
        ProductBasicFieldsView(
            name: $state.draft.name,
            type: $state.draft.type,
            nameError: state.validationMessage(for: .name),
            typeError: state.validationMessage(for: .type)
        )

        ProductPhotoPicker(
            selection: $selectedPhoto, imageData: state.image, isLoading: state.photo.isLoading,
            error: state.photo.error, loader: photoLoader, remove: removePhoto
        )

        ProductExtraFieldsView(draft: $state.draft, validationMessage: state.validationMessage)

        ProductDeletionSection(
            counts: ProductDeletionCounts(items: items),
            fetchErrorMessage: _items.fetchError?.localizedDescription,
            deletionError: deletionError,
            onRequestDelete: { requestDeletion() }
        )
    }
}

private func requestDeletion() {
    deletionError = nil
    showsDeletionConfirmation = true
}

}

if let deletionError {
    Text(deletionError)
        .foregroundStyle(.red)
        .accessibilityIdentifier("product-detail-deletion-error")
}

Button("商品を削除", role: .destructive, action: onRequestDelete)
    .disabled(fetchErrorMessage != nil || !counts.canDelete)
    .accessibilityIdentifier("product-detail-delete")
